std::vector<int> V = {10, 20, 30};

// Forward Traversal using iterators (Bidirectional/Random Access)
auto it = V.begin();
while (it != V.end()) {
    std::cout << *it << " "; // Dereference
    ++it;                    // Advance
}
// Constant iterator access: V.cbegin(), V.cend()

std::vector<int> V = {1, 2, 3};
std::list<int> L;

// Output Iterator: std::back_inserter (for containers with push_back)
// Copies elements from V to L
std::copy(V.begin(), V.end(),
          std::back_inserter(L));

// Input/Output Iterators for Streams
std::ostream_iterator<int> out(std::cout, ", ");
*out = 42; // Prints "42, "

std::set<std::string> S = {"alpha", "beta", "gamma"};

// Reverse Iteration (Bidirectional/Random Access Containers only)
for (auto rit = S.rbegin(); rit != S.rend(); ++rit) {
    std::cout << *rit << "\n";
}
// S.rbegin() points to "gamma"
// S.rend() points just before "alpha"

std::map<int, double> M = {{1, 1.1}, {2, 2.2}};

// Associative Container Iteration (Key/Value pairs)
auto it = M.begin(); // it is a BidirectionalIterator
if (it != M.end()) {
    std::cout << "Key: " << it->first
              << ", Value: " << (*it).second;
    it++;
}
